referenceSolutions.javascript:
export function solve(root, requested) {
  const nodes = [];
  const visit = (n) => {
    nodes.push(n);
    for (const c of n.children) visit(c);
  };
  visit(root);
  return nodes.filter((n) => requested.every((c) => n.classes.includes(c))).map((n) => n.id);
}

referenceSolutions.typescript:
export function solve(root: any, requested: string[]): any {
  const nodes: any[] = [];
  const visit = (n: any): void => {
    nodes.push(n);
    for (const c of n.children) visit(c);
  };
  visit(root);
  return nodes.filter((n) => requested.every((c) => n.classes.includes(c))).map((n) => n.id);
}
